import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import { usePopperContext } from "@kobalte/core/popper";
import * as TooltipPrimitive from "@kobalte/core/tooltip";
import type { JSX, ValidComponent } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import type { Component } from "solid-js";

import { omit } from "solid-js";

const Tooltip: Component<TooltipPrimitive.TooltipRootProps> = (props) => {
  return (
    <TooltipPrimitive.Root
      data-slot="tooltip"
      placement="top"
      gutter={5}
      openDelay={0}
      {...props}
    />
  );
};

type TooltipTriggerProps<T extends ValidComponent = "button"> =
  & TooltipPrimitive.TooltipTriggerProps<T>
  & { class?: string | undefined };

const TooltipTrigger = <T extends ValidComponent = "button">(
  props: PolymorphicProps<T, TooltipTriggerProps<T>>,
) => {
  return (
    <TooltipPrimitive.Trigger
      data-slot="tooltip-trigger"
      {...(props as TooltipTriggerProps)}
    />
  );
};

type TooltipContentProps<T extends ValidComponent = "div"> =
  & TooltipPrimitive.TooltipContentProps<T>
  & { class?: string | undefined; children?: JSX.Element };

const TooltipContent = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, TooltipContentProps<T>>,
) => {
  const popper = usePopperContext();
  const side = () => popper.currentPlacement().split("-")[0];
  const local = props as TooltipContentProps;
  const others = omit(local, "class", "children");
  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Content
        data-slot="tooltip-content"
        data-side={side()}
        class={cn(
          "data-expanded:animate-in data-expanded:fade-in-0 data-expanded:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 inline-flex items-center gap-1.5 rounded-xl px-3 py-1.5 text-xs has-data-[slot=kbd]:pr-1.5 **:data-[slot=kbd]:relative **:data-[slot=kbd]:isolate **:data-[slot=kbd]:z-50 **:data-[slot=kbd]:rounded-lg z-50 w-fit max-w-xs origin-(--kb-tooltip-content-transform-origin) bg-foreground text-background",
          local.class,
        )}
        {...others}
      >
        {local.children}
        <TooltipPrimitive.Arrow
          data-side={side()}
          size={10}
          class="size-2.5 rotate-45 rounded-[2px] *:hidden data-[side=top]:translate-y-[calc(-50%_-_2px)] data-[side=bottom]:translate-y-[calc(50%_+_2px)] data-[side=left]:translate-x-[calc(-50%_-_2px)] data-[side=right]:translate-x-[calc(50%_+_2px)] z-50 bg-foreground"
        />
      </TooltipPrimitive.Content>
    </TooltipPrimitive.Portal>
  );
};

export { Tooltip, TooltipContent, TooltipTrigger };
